<!DOCTYPE html><html lang="tr"><head>    <meta charset="UTF-8">    <title>php tablo</title></head><body><h3>Satır ve sütun sayısını girerek, 0-100 arasında rastgele sayılar barındıran hücrelere sahip bir tablo oluşturabilirsinz</h3><form method="post">    Satır Sayısı: <input type="number" name="satir" >    Sütun Sayısı: <input type="number" name="sutun" >    <button type="submit">Oluştur</button></form><br><?phpif ($_POST) {      if (empty($_POST["satir"]) || empty($_POST["sutun"]) ||         $_POST["satir"] < 1 || $_POST["sutun"] < 1) {        echo "<p style='color:red; font-weight:bold;'>Lütfen geçerli bir değer yazınız.</p>";    } else {        $satir = intval($_POST["satir"]);        $sutun = intval($_POST["sutun"]);        echo "<table border='1' cellpadding='20' cellspacing='05'>";        for ($i = 0; $i < $satir; $i++) {    echo "<tr>";    for ($j = 0; $j < $sutun; $j++) {                $rastgeleSayi = rand(1, 100);        $rastgeleRenk = sprintf('#%06X', mt_rand(0, 0xFFFFFF));        echo "<td style='color: $rastgeleRenk; font-weight:bold;'>$rastgeleSayi</td>";    }    echo "</tr>";}        echo "</table>";    }}?></body></html>